 const submit=async e=>{e.preventDefault();setError('');try{const body={...d,dueDate:d.dueDate||undefined,startDate:d.startDate||undefined,ownerId:d.ownerId||undefined};if(edit){delete body.sectorId;delete body.startDate;if(!body.dueDate)delete body.dueDate;const result=await api('/projects/'+id,{method:'PATCH',body});nav('/projects/'+result.project._id);}else{const result=await api('/projects',{method:'POST',body});nav('/projects/'+result.project._id);}}catch(e){setError(e.message)}};
