function Assignments(){const {data,busy,error}=useLoad('/assignments');return <><h1>Zaduženja predsednika</h1><Loading busy={busy} error={error}/>{data?.items?.map(a=><Go key={a._id} to={'/assignments/'+a._id}>{a.title} · {label(a.status)}</Go>)}</>}
function AssignmentDetail(){const {id}=useParams(),{user}=useContext(Auth),{data,reload}=useLoad('/assignments/'+id),[status,setStatus]=useState('in_progress'),[response,setResponse]=useState('');const a=data?.assignment;return <><h1>{a?.title||'Zaduženje'}</h1>{a&&<><Panel><p>{a.description}</p><Pill value={a.status}/><p>Rok: {day(a.dueDate)}</p></Panel>{user.role==='manager'&&<Panel title="Ažuriraj status"><Field label="Status"><select value={status} onChange={e=>setStatus(e.target.value)}>{['new','in_progress','blocked','done'].map(x=><option key={x} value={x}>{label(x)}</option>)}</select></Field><Field label="Odgovor"><textarea value={response} onChange={e=>setResponse(e.target.value)}/></Field><button className="primary" onClick={async()=>{await api('/assignments/'+id,{method:'PATCH',body:{status,response}});reload()}}>Sačuvaj</button></Panel>}<Panel title="Komentari"><Thread type="assignment" id={id}/></Panel></>}</>}
function AssignmentNew(){const nav=useNavigate(),{data:sectors}=useLoad('/sectors'),{data:people}=useLoad('/users'),[d,setD]=useState({sectorId:'',assignedTo:'',title:'',description:'',dueDate:''}),[err,setErr]=useState('');const submit=async e=>{e.preventDefault();try{const result=await api('/assignments',{method:'POST',body:{...d,dueDate:d.dueDate||undefined}});nav('/assignments/'+result.assignment._id);}catch(e){setErr(e.message)}};return <><h1>Novo zaduženje rukovodiocu</h1><form onSubmit={submit}><Field label="Sektor"><select required value={d.sectorId} onChange={e=>setD(o=>({...o,sectorId:e.target.value,assignedTo:''}))}><option value="">Izaberite</option>{sectors?.items?.map(s=><option key={s._id} value={s._id}>{s.name}</option>)}</select></Field><Field label="Rukovodilac"><select required value={d.assignedTo} onChange={e=>setD(o=>({...o,assignedTo:e.target.value}))}><option value="">Izaberite</option>{people?.items?.filter(p=>p.role==='manager'&&String(p.sector)===d.sectorId).map(p=><option key={p._id} value={p._id}>{p.firstName} {p.lastName}</option>)}</select></Field><Field label="Naslov"><input required value={d.title} onChange={e=>setD(o=>({...o,title:e.target.value}))}/></Field><Field label="Opis"><textarea rows={4} value={d.description} onChange={e=>setD(o=>({...o,description:e.target.value}))}/></Field><Field label="Rok"><input type="date" value={d.dueDate} onChange={e=>setD(o=>({...o,dueDate:e.target.value}))}/></Field><Alert text={err}/><Submit>Pošalji zaduženje</Submit></form></>}
function RequestNew(){const nav=useNavigate(),[d,setD]=useState({title:'',description:'',type:'question',referenceType:'sector'}),[err,setErr]=useState('');const submit=async e=>{e.preventDefault();try{const result=await api('/requests',{method:'POST',body:d});nav('/requests/'+result.request._id)}catch(e){setErr(e.message)}};return <><h1>Pitanje za predsednika</h1><p className="muted">Uputite zahtev, pitanje ili prijavite problem koji zahteva odluku.</p><form onSubmit={submit}><Field label="Naslov"><input required value={d.title} onChange={e=>setD(o=>({...o,title:e.target.value}))}/></Field><Field label="Vrsta zahteva"><select value={d.type} onChange={e=>setD(o=>({...o,type:e.target.value}))}><option value="question">Pitanje</option><option value="approval">Odobrenje</option><option value="problem">Problem</option></select></Field><Field label="Opis"><textarea required rows={5} value={d.description} onChange={e=>setD(o=>({...o,description:e.target.value}))}/></Field><Alert text={err}/><Submit>Pošalji predsedniku</Submit></form></>}
function RequestDetail(){const {id}=useParams(),{user}=useContext(Auth),{data,reload}=useLoad('/requests/'+id),[decision,setDecision]=useState(''),[err,setErr]=useState('');const r=data?.request;return <><Go to="/attention">Nazad</Go><h1>{r?.title||'Zahtev'}</h1>{r&&<><Panel><Pill value={r.status}/><p>{r.description}</p>{r.decision&&<p><strong>Odluka:</strong> {r.decision}</p>}</Panel>{user.role==='president'&&r.status!=='closed'&&<Panel title="Odgovor predsednika"><Field label="Odgovor / odluka"><textarea value={decision} onChange={e=>setDecision(e.target.value)}/></Field><Alert text={err}/><button className="primary" onClick={async()=>{try{await api('/requests/'+id+'/decision',{method:'PATCH',body:{status:'answered',decision}});reload();}catch(e){setErr(e.message)}}}>Pošalji odgovor</button></Panel>}<Panel title="Razgovor"><Thread type="request" id={id}/></Panel></>}</>}
function Admin(){const {data,reload}=useLoad('/admin/registrations'),{data:sectors,reload:reloadSectors}=useLoad('/sectors'),[error,setError]=useState(''),[sector,setSector]=useState({name:'',code:''});const approve=async(u,role)=>{try{await api('/admin/users/'+u._id+'/approve',{method:'PATCH',body:{role,sectorId:u.sector?._id||u.sector}});reload()}catch(e){setError(e.message)}};
 const add=async e=>{e.preventDefault();try{await api('/admin/sectors',{method:'POST',body:sector});setSector({name:'',code:''});reloadSectors();}catch(e){setError(e.message)}};
 return <><h1>Administracija</h1><p className="muted">Odobravanje korisnika i sektora.</p><Alert text={error}/><Panel title="Registracije na čekanju">{data?.items?.length===0&&<p>Nema novih prijava.</p>}{data?.items?.map(u=><div className="comment" key={u._id}><strong>{u.firstName} {u.lastName}</strong><p>{u.email} · {u.jobTitle} · {u.sector?.name}</p><p>{u.requestedManager?'Traži ulogu rukovodioca':'Zaposleni'}</p><div className="row gap"><button className="primary" onClick={()=>approve(u,u.requestedManager?'manager':'employee')}>Odobri</button><button onClick={async()=>{await api('/admin/users/'+u._id+'/reject',{method:'PATCH',body:{}});reload()}}>Odbij</button></div></div>)}</Panel><Panel title="Dodaj sektor"><form onSubmit={add}><Field label="Naziv"><input required value={sector.name} onChange={e=>setSector(o=>({...o,name:e.target.value}))}/></Field><Field label="Šifra"><input required value={sector.code} onChange={e=>setSector(o=>({...o,code:e.target.value}))}/></Field><Submit>Sačuvaj sektor</Submit></form><p className="muted small">{sectors?.items?.map(s=>s.name).join(', ')}</p></Panel></>}
function App({presidentEntry}){const [user,setUser]=useState(null),[ready,setReady]=useState(false),[newNotification,setNewNotification]=useState(false),[logoutError,setLogoutError]=useState(''),loc=useLocation(),nav=useNavigate();
 const [presidentCredential,setPresidentCredential]=useState(()=>presidentEntry?.takeKey?.()||null),[entryError,setEntryError]=useState(''),[entryBusy,setEntryBusy]=useState(false);
 const entryPath=isPresidentEntryPath(loc.pathname);
 const openPresident=async()=>{setEntryBusy(true);setEntryError('');try{const d=await api('/auth/president-link',{method:'POST',body:{key:presidentCredential},retry:false});if(d.user?.role!=='president')throw Error('Predsednički pristup nije potvrđen.');setToken(d.accessToken);setUser(d.user);setPresidentCredential(null);connectSocket(()=>setNewNotification(true));nav('/',{replace:true});}catch(e){setEntryError(e.message);}finally{setEntryBusy(false);}};
 const [logoutBusy,setLogoutBusy]=useState(false),logoutLock=useRef(false);
 useEffect(()=>{const expired=()=>{setUser(null);setNewNotification(false);nav(user?.role==='president'||isPresidentEntryPath(loc.pathname)?'/predsednik':'/login',{replace:true});};window.addEventListener('zepter:session-expired',expired);return()=>window.removeEventListener('zepter:session-expired',expired);},[nav,user?.role,loc.pathname]);
 useEffect(()=>{let active=true;const start=async()=>{try{if(presidentEntry?.invalid){setEntryError('Lični link nije važeći. Otvorite originalni link.');return;}if(presidentCredential){await openPresident();return;}const d=await bootstrap();if(active&&d?.user){setUser(d.user);connectSocket(()=>setNewNotification(true));}}finally{if(active)setReady(true);}};start();return()=>{active=false;disconnectSocket();};},[]);
 const login=async(email,password)=>{const d=await api('/auth/login',{method:'POST',body:{email,password},retry:false});setToken(d.accessToken);setUser(d.user);setLogoutError('');setNewNotification(false);connectSocket(()=>setNewNotification(true));};
 const logout=async()=>{if(logoutLock.current)return;logoutLock.current=true;setLogoutBusy(true);setLogoutError('');setNewNotification(false);setUser(null);nav(user?.role==='president'?'/predsednik':'/login',{replace:true});try{await logoutSession();}catch{setLogoutError('Serverska odjava nije potvrđena. Proverite vezu i ponovite odjavu pre zatvaranja aplikacije.');}finally{logoutLock.current=false;setLogoutBusy(false);}};
 if(!ready)return entryPath?<PresidentEntry busy/>:<div className="login">Učitavanje Zepter aplikacije…</div>;
 if(logoutBusy)return <div className="login" role="status">Odjava je u toku…</div>;
 const publicPage=['/login','/register'].includes(loc.pathname);
 if(entryPath&&user?.role!=='president')return <><PresidentEntry busy={entryBusy} error={entryError} canRetry={!!presidentCredential} onRetry={openPresident}/>{logoutError&&<div className="employee-form-error" role="alert"><p>{logoutError}</p><button onClick={logout}>Ponovi odjavu</button></div>}</>;
 if(!user)return <Auth.Provider value={{login}}>{logoutError&&<div role="alert" className="employee-form-error"><p>{logoutError}</p><button onClick={logout}>Ponovi odjavu</button></div>}<Routes><Route path="/register" element={<Register/>}/><Route path="*" element={<Login/>}/></Routes></Auth.Provider>;
 if(publicPage)return <Navigate to="/" replace/>;
 return <Auth.Provider value={{user,logout,newNotification}}><Layout><Routes>
 <Route path="/" element={<Home/>}/><Route path="/predsednik" element={<Navigate to="/" replace/>}/><Route path="/president" element={<Navigate to="/" replace/>}/><Route path="/sectors" element={<Sectors/>}/><Route path="/sectors/:id" element={<Sector/>}/>
 <Route path="/projects" element={<Projects/>}/><Route path="/projects/new" element={<ProjectForm/>}/><Route path="/projects/:id/edit" element={<ProjectForm/>}/><Route path="/projects/:id/new-activity" element={<NewActivity/>}/><Route path="/projects/:id" element={<ProjectDetail/>}/><Route path="/activities/:id" element={<ActivityDetail/>}/>
 <Route path="/ideas" element={<Ideas/>}/><Route path="/ideas/new" element={<IdeaCreate/>}/><Route path="/ideas/:id" element={<IdeaDetail/>}/>
 <Route path="/reports" element={<Reports/>}/><Route path="/reports/new" element={<ReportCreate/>}/><Route path="/reports/:id" element={<ReportDetail/>}/><Route path="/daily" element={<Daily/>}/>
 <Route path="/notifications" element={<Notifications/>}/><Route path="/attention" element={<Attention/>}/><Route path="/my-comments" element={<MyComments/>}/>
 <Route path="/requests/new" element={<RequestNew/>}/><Route path="/requests/:id" element={<RequestDetail/>}/><Route path="/assignments/new" element={<AssignmentNew/>}/><Route path="/assignments" element={<Assignments/>}/><Route path="/assignments/:id" element={<AssignmentDetail/>}/><Route path="/admin" element={<Admin/>}/>
 <Route path="*" element={<Navigate to="/" replace/>}/></Routes></Layout></Auth.Provider>;
}
export default App;
